import sys

def factorial(n):
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

tokens = sys.stdin.read().split()
n = int(tokens[0])

if 0 <= n <= 8:
    print(factorial(n))
else:
    print("invalid")
